# Builds the Zenodo archive: the full project folder, as on GitHub (including
# the website in docs/), plus the files that are too large for GitHub or
# generated by the pipeline (fitted models, cached online data and slow steps,
# intermediate objects, figures, tables and reports). Unzipped, it reproduces
# all results without refitting the models or querying online services.
#
# The archive is split into several zip files of at most ~400 MB, grouped by
# content, so that each can be uploaded (and downloaded) on its own. Unzipping
# all of them into the same folder restores the complete project.
# MANIFEST.csv lists which zip file contains each file.
#
# Not included: third-party input data in data/ (downloaded automatically
# from pinned versions; see data/README.md). The cached IUCN Red List
# categories (species name and category only, Red List version 2025-2) are
# included, with attribution in data/README.md.
#
# Run after a complete run of run_all.R and renv::snapshot().

max_part_mb <- 400

project_dir <- here::here()
archive_dir <- file.path(project_dir, "archive")
dir.create(archive_dir, showWarnings = FALSE)
unlink(list.files(archive_dir, pattern = "\\.(zip|csv)$", full.names = TRUE))

old_wd <- setwd(project_dir)
on.exit(setwd(old_wd), add = TRUE)

all_files <- list.files(".", recursive = TRUE, all.files = TRUE, no.. = TRUE)
all_files <- sub("^\\./", "", all_files)

keep <- all_files[
  # Code, documentation, the reference databases and the website
  grepl("^(R/|0_Get_reference_data/|data/CRABS/|docs/)", all_files) |
  all_files %in% c("data/README.md", "README.md", "LICENSE", "CITATION.cff",
                   "Pipeline.Rproj", "run_all.R", "make_archive.R",
                   "renv.lock", ".Rprofile", "renv/activate.R", ".gitignore") |
  grepl("^[0-9]_.*\\.Rmd$", all_files) |
  # Generated outputs
  grepl("^output/", all_files)
]

# Group the files by content
group <- ifelse(grepl("^output/models/", keep), "3_models",
         ifelse(grepl("^output/(cache|intermediate)/", keep), "4_cache_and_intermediate",
         ifelse(grepl("^output/", keep), "2_outputs", "1_code_data_website")))

files <- data.frame(file = keep, group = group, mb = file.size(keep) / 1e6)
files <- files[order(files$group, files$file), ]

# Within each group, fill parts of at most max_part_mb (a larger single file gets its own part)
files$part <- NA_integer_
for (g in unique(files$group)) {
  idx <- which(files$group == g)
  part <- 1L; used <- 0
  for (i in idx) {
    if (used > 0 && used + files$mb[i] > max_part_mb) { part <- part + 1L; used <- 0 }
    files$part[i] <- part
    used <- used + files$mb[i]
  }
}

n_parts <- tapply(files$part, files$group, max)
files$zip <- ifelse(n_parts[files$group] > 1,
                    sprintf("Luypaert_et_al_2026_%s_part%d.zip", files$group, files$part),
                    sprintf("Luypaert_et_al_2026_%s.zip", files$group))

# zip::zip needs no external zip program (unlike utils::zip on Windows)
for (z in unique(files$zip)) {
  zip::zip(file.path(archive_dir, z), files = files$file[files$zip == z], mode = "mirror")
}

write.csv(files[, c("file", "zip")], file.path(archive_dir, "MANIFEST.csv"), row.names = FALSE)

# Summary: one line per zip file, with its MD5 checksum (Zenodo shows the same)
zips <- unique(files$zip)
summary <- data.frame(
  zip     = zips,
  files   = as.vector(table(files$zip)[zips]),
  size_MB = round(file.size(file.path(archive_dir, zips)) / 1e6, 1),
  md5     = unname(tools::md5sum(file.path(archive_dir, zips)))
)
print(summary, row.names = FALSE)
message(sprintf("Total: %d files in %d zip files, %.1f MB",
                nrow(files), length(zips), sum(summary$size_MB)))
